let LANG = 'zh'
function t(key, vars) {
  const dict = LANGS[LANG] || LANGS.zh
  let text = dict[key] ?? LANGS.zh[key] ?? key
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v))
  return text
}

